/* 两侧的障子：从天花板下面一直落到地上；开合时整扇滑进滑出 */
@media screen and (min-width: 1001px) {
    .fillLeft,
    .fillRight {
        top: calc(var(--topBarBlockSize) + 14px);
        height: calc(100dvh - var(--topBarBlockSize) - 14px);
        max-height: none;
        padding: 10px 22px;
        box-shadow: none;
        /* 拉门：门从正文柱那根柱子后面拉出来，滑向屏幕边；关的时候滑回柱子后面。
         * 柱子后面那截用 clip-path 裁掉（门一边往外滑、裁切一边往外放，两者同步，看上去就是从柱后露出来）。
         * 末尾那一下是门碰到门框，轻轻一顿 */
        transition-property: transform, clip-path, display;
        transition-duration: var(--kt-slide);
        transition-timing-function: linear(0, 0.08 12%, 0.32 30%, 0.7 55%, 0.93 75%, 1.012 88%, 1);
        transition-behavior: allow-discrete;
    }

    .fillLeft {
        border-left: 0;
        transform: translateX(100%);
        clip-path: inset(0 100% 0 0);
    }

    .fillRight {
        border-right: 0;
        transform: translateX(-100%);
        clip-path: inset(0 0 0 100%);
    }

    .fillLeft.openDrawer,
    .fillRight.openDrawer {
        height: calc(100dvh - var(--topBarBlockSize) - 14px);
        transform: none;
        clip-path: inset(0);

        @starting-style {
            height: calc(100dvh - var(--topBarBlockSize) - 14px);
        }
    }

    @starting-style {
        .fillLeft.openDrawer {
            transform: translateX(100%);
            clip-path: inset(0 100% 0 0);
        }

        .fillRight.openDrawer {
            transform: translateX(-100%);
            clip-path: inset(0 0 0 100%);
        }
    }

    body.reduced-motion :is(.fillLeft, .fillRight) {
        transition-duration: 0s;
    }

    /* 引手：门边上一个小小的凹槽 */
    .fillLeft::after,
    .fillRight::after {
        content: '';
        position: absolute;
        top: 50%;
        width: 8px;
        height: 28px;
        border-radius: 4px;
        background: var(--kt-wood-d);
        box-shadow: inset 0 0 0 2px color-mix(in srgb, var(--kt-wood) 60%, #000);
        pointer-events: none;
    }

    .fillLeft::after {
        right: 2px;
    }

    .fillRight::after {
        left: 2px;
    }
}

/* 右边是雪见障子：下半截装玻璃，透出外面的园子（你的背景图） */
@media screen and (min-width: 1001px) {
    #right-nav-panel {
        padding-bottom: calc(var(--kt-yukimi) + 12px);
        background:
            var(--kt-shoji-bars) left top / 100% calc(100% - var(--kt-yukimi)) no-repeat,
            var(--kt-shade-near) calc(50% + var(--kt-sway)) calc(var(--kt-sway) * 0.3) / calc(100% + 40px) auto no-repeat,
            var(--kt-shade-far) calc(50% - var(--kt-sway) * 0.6) 0 / calc(100% + 40px) auto no-repeat,
            var(--kt-shoji-paper) left top / 100% calc(100% - var(--kt-yukimi)) no-repeat;
        background-color: transparent;
    }

    /* 玻璃：两扇，中间一根竖框；上边一根横木（腰板的上框），下边一根下框。
     * 玻璃本身稍微糊一点、带一点绿灰，玻璃面上有屋里的暖光和两道斜的反光，靠框的地方暗一圈 */
    #right-nav-panel::before {
        content: '';
        position: absolute;
        left: 0;
        right: 0;
        bottom: 0;
        height: var(--kt-yukimi);
        background:
            /* 上框、下框、中间的竖框（竖框两边各一道细缝） */
            linear-gradient(var(--kt-wood), var(--kt-wood) 5px, var(--kt-wood-d) 5px 7px, transparent 7px) top / 100% 100% no-repeat,
            linear-gradient(var(--kt-wood-d), var(--kt-wood-d)) bottom / 100% 9px no-repeat,
            linear-gradient(90deg, transparent calc(50% - 3.5px), var(--kt-wood-d) 0 calc(50% - 2.5px), var(--kt-wood) 0 calc(50% + 2.5px), var(--kt-wood-d) 0 calc(50% + 3.5px), transparent 0),
            /* 反光：每扇一道宽的、一道细的 */
            linear-gradient(112deg, transparent 8%, rgba(255, 255, 255, var(--kt-glass)) 14%, transparent 26%, transparent 33%, rgba(255, 255, 255, calc(var(--kt-glass) * 0.7)) 35% 36%, transparent 38%) left / 50% 100% no-repeat,
            linear-gradient(112deg, transparent 22%, rgba(255, 255, 255, calc(var(--kt-glass) * 0.8)) 30%, transparent 44%, transparent 58%, rgba(255, 255, 255, calc(var(--kt-glass) * 0.6)) 60% 61%, transparent 63%) right / 50% 100% no-repeat,
            /* 屋里的光照在玻璃上半截 */
            linear-gradient(color-mix(in srgb, var(--kt-paper) calc(var(--kt-glass) * 140%), transparent) 7px, transparent 45%),
            /* 玻璃的颜色 */
            linear-gradient(color-mix(in srgb, var(--kt-moss-d) 10%, transparent), color-mix(in srgb, var(--kt-moss-d) 16%, transparent));
        box-shadow: inset 0 9px 10px -6px rgba(0, 0, 0, 0.28), inset 0 -12px 10px -8px rgba(0, 0, 0, 0.25);
        backdrop-filter: blur(1.2px) saturate(1.08);
        -webkit-backdrop-filter: blur(1.2px) saturate(1.08);
        pointer-events: none;
    }
}

