/* ==== end themes/koke/fallen.css ==== */

:root {
    --kt-fall: none;          /* 飞石上的落物 */
    --kt-fall-rake: none;     /* 耙纹上的落物（雪不落在耙纹上：盖住就看不见纹了） */
}

@container style(--kt-season: tsuyu) {
    body {
        --kt-fall: var(--kt-fall-tsuyu);
        --kt-fall-rake: var(--kt-fall-tsuyu);
    }
}

@container style(--kt-season: momiji) {
