        --kt-moss-d: var(--kt-koyo-moss-d);
        --kt-maple: var(--kt-koyo-leaf);
    }
}

@container style(--kt-season: yuki) {
    body {
        --kt-fall: var(--kt-fall-yuki);
        --kt-moss-l: var(--kt-yuki-moss-l);
        --kt-moss-d: var(--kt-yuki-moss-d);
        --kt-maple: var(--kt-yuki-leaf);
