    --SmartThemeBorderColor: var(--kt-night-wood) !important;
    --SmartThemeCheckboxTickColor: var(--kt-night-column);
    color-scheme: dark;

    --kt-wood: var(--kt-night-wood);
    --kt-wood-d: var(--kt-night-wood-d);
    --kt-wall: var(--kt-night-wall);
    --kt-ceil: var(--kt-night-ceil);
    --kt-paper-e: var(--kt-night-paper-e);
    --kt-tatami: var(--kt-night-tatami);
    --kt-heri: var(--kt-night-heri);
    --kt-stone: var(--kt-night-stone);
    --kt-stone-l: var(--kt-night-stone-l);
    --kt-moss-l: var(--kt-night-moss-l);
    --kt-moss-d: var(--kt-night-moss-d);
    --kt-sand: var(--kt-night-sand);
    --kt-water: var(--kt-night-water);
    --kt-tsuchi: var(--kt-night-tsuchi);
    --kt-suna: var(--kt-night-suna);
    --kt-koshi: var(--kt-night-koshi);
    --kt-take: var(--kt-night-take);
    --kt-take-d: var(--kt-night-take-d);
    --kt-hashira: var(--kt-night-hashira);
    --kt-kokera: var(--kt-night-kokera);
    --kt-straw: var(--kt-night-straw);

    
    --kt-shoji-paper: radial-gradient(130% 90% at 50% 105%, color-mix(in srgb, var(--kt-night-lamp) 14%, var(--kt-paper)), var(--kt-paper) 60%, var(--kt-paper-e));
    --kt-kumiko: 2px solid var(--kt-wood);
    
    --fx-surface: color-mix(in srgb, var(--kt-paper) 65%, #000);
    
    --kt-glass: 0.07;
}

:root.dn-night body {
