    position: relative;
    width: 20px;
    height: 20px;
    background:
        radial-gradient(circle at 50% 44%, color-mix(in srgb, var(--kt-night-lamp) 60%, transparent), transparent 72%),
        linear-gradient(var(--kt-night-lamp), var(--kt-night-lamp)) 8px 7.5px / 4px 3px no-repeat;
